-- Select specific columns
SELECT name, salary FROM employees;

-- All columns (avoid in production)
SELECT * FROM employees;

-- With alias, filter, sort, limit
SELECT name AS employee_name, salary
FROM employees
WHERE salary > 50000
ORDER BY salary DESC
LIMIT 10;

-- Unique departments
SELECT DISTINCT department FROM employees;

-- DISTINCT on multiple columns (unique combinations)
SELECT DISTINCT department, job_title FROM employees;

-- DISTINCT in aggregate
SELECT COUNT(DISTINCT department) FROM employees;

-- WRONG: = NULL never matches anything
SELECT * FROM employees WHERE manager_id = NULL;

-- CORRECT: use IS NULL
SELECT * FROM employees WHERE manager_id IS NULL;

-- Replace NULL with default value
SELECT name, COALESCE(bonus, 0) AS bonus FROM employees;

-- MySQL IFNULL (same as COALESCE for 2 args)
SELECT name, IFNULL(bonus, 0) FROM employees;

-- Page 1: rows 1-10
SELECT * FROM products ORDER BY id LIMIT 10 OFFSET 0;

-- Page 2: rows 11-20
SELECT * FROM products ORDER BY id LIMIT 10 OFFSET 10;

-- Page 3: rows 21-30
SELECT * FROM products ORDER BY id LIMIT 10 OFFSET 20;

-- Formula: OFFSET = (page - 1) * pageSize

-- Sort by salary descending
SELECT name, salary FROM employees ORDER BY salary DESC;

-- Multi-column sort: department ASC, then salary DESC
SELECT name, department, salary
FROM employees
ORDER BY department ASC, salary DESC;

-- Sort by column position (1=first selected col)
SELECT name, salary FROM employees ORDER BY 2 DESC;

-- ERROR: alias 'high_salary' unknown in WHERE (SELECT runs after WHERE)
SELECT salary * 1.1 AS high_salary FROM emp WHERE high_salary > 50000;

-- CORRECT: use original column in WHERE
SELECT salary * 1.1 AS high_salary FROM emp WHERE salary > 45455;

-- ERROR: aggregate in WHERE
SELECT dept FROM emp WHERE COUNT(*) > 5 GROUP BY dept;

-- CORRECT: aggregate filter goes in HAVING
SELECT dept FROM emp GROUP BY dept HAVING COUNT(*) > 5;
